def arms(p,cx,cy,kind='bone'):
    s=SWING[p.pose];rear=[(cx-7,cy-6),(cx-12,cy+1+s/3),(cx-12-s/2,cy+8)];front=[(cx+7,cy-6),(cx+12+s/3,cy-2-s/3),(min(53,cx+17+s/2),cy-5-s/2)]
    if p.pose=='windup':front=[(cx+7,cy-6),(cx+10,cy-12),(cx+6,cy-19)]
    if p.pose=='hit':front=[(cx+7,cy-6),(cx+7,cy+3),(cx,cy+4)]
    if p.pose=='attack' and kind=='club':front=[(cx+7,cy-6),(cx+13,cy-1),(cx+9,cy-1)]
    for pts in (rear,front):
        if kind in ('bone','club'):bone(p,pts,4)
        else:p.joint(pts,6,'C','u','c')
    return rear[-1],front[-1]
def blade(p,x,y,red=False):
    if p.pose=='attack':tip=(59,y-2)
    elif p.pose=='windup':tip=(x-6,max(3,y-23))
    elif p.pose=='hit':tip=(x-9,y-14)
    else:tip=(min(59,x+8),max(3,y-25))
    tx,ty=tip;p.line([(x,y+4),(x,y)],'o',4);p.line([(x,y+3),(x,y)],'B',2);p.poly([(x-5,y),(x-4,y-2),(x+5,y-2),(x+6,y),(x+2,y+1),(x-2,y+1)],'y',True)
    p.poly([(x-1,y-3),(tx-2,ty+4),(tx,ty),(tx+1,ty+3),(x+2,y-3)],'m',True);p.line([(x,y-3),(tx,ty+2)],'h');p.line([(x+1,y-4),(tx+1,ty+4)],'R' if red else 'g');p.cluster(x-3,y-1,['ii'])

def skeletal(slug,pose,cell):
    p=Pixels(pose,cell);archer=slug=='skeleton-archer'
    if pose=='dead':
        for pts in [[(7,55),(16,53),(23,57)],[(15,48),(23,51),(29,54)],[(27,58),(32,55),(36,59)]]:bone(p,pts,3)
        p.poly([(18,52),(23,48),(29,50),(28,55),(22,57)],'t',True);p.line([(21,51),(25,52)],'i');p.part='head';skull(p,46,49,.85);p.part='fixed';p.poly([(28,59),(33,57),(36,59),(35,60),(29,60)],'t',True)
        if archer:p.line([(6,43),(4,48),(6,53),(11,57)],'B',2);p.line([(6,43),(11,57)],'y')
        else:p.poly([(8,57),(16,55),(18,58),(11,60)],'B',True)
        return p.im
    # Near/far femurs, kneecaps and twin tibias are separately rendered.
    for part,hip,knee,foot in [('leftleg',(27,40),(20,50),(16,59)),('rightleg',(34,40),(40,50),(44,59))]:
        p.part=part;bone(p,[hip,knee,(foot[0],55)],4,part=='rightleg');p.poly([(foot[0]-4,56),(foot[0]+1,56),(foot[0]+5,58),(foot[0]+5,60),(foot[0]-5,60),(foot[0]-6,59)],'t',True);p.line([(foot[0]-3,58),(foot[0]+2,58)],'i');p.cluster(foot[0]+1,59,['Bty'])
    p.part='body';cx=30;cy=32
    if archer:
        p.poly([(16,15),(20,13),(24,31),(23,39),(18,38)],'b',True);p.line([(18,17),(22,36)],'B',2);p.line([(18,16),(13,8)],'t');p.line([(21,16),(17,6)],'t');p.line([(22,18),(20,10)],'y');p.cluster(13,8,['ww','t.']);p.poly([(20,25),(24,23),(28,27),(27,32),(22,31)],'b',True)
    rear,front=arms(p,cx,cy,'bone' if archer else 'club')
    p.poly([(23,23),(29,21),(35,23),(40,28),(38,37),(34,41),(25,39),(21,34)],'B',True)
    p.poly([(26,22),(31,22),(31,38),(27,37)],'t');p.line([(28,23),(28,37)],'i',2)
    for j in range(4):
        y=24+j*4
        p.poly([(23,y),(25,y-1),(28,y+1),(34,y+1),(38,y-1),(39,y+1),(35,y+4),(29,y+4),(25,y+2),(22,y+2)],'t',True);p.line([(24,y),(28,y+2),(34,y+2),(37,y)],'i');p.line([(27,y+3),(34,y+3)],'B')
    p.poly([(23,39),(28,37),(34,38),(37,41),(34,45),(31,43),(27,44),(22,42)],'t',True);p.poly([(25,39),(29,39),(30,41),(26,42)],'i');p.poly([(32,40),(35,40),(33,43)],'B');p.line([(22,44),(32,46),(35,44)],'r',3);p.cluster(25,44,['Rp','RR'])
    # Fingers are three individually shaded bones around the grip.
    for x,y in (rear,front):
        p.poly([(x-2,y-2),(x+2,y-2),(x+4,y),(x+3,y+3),(x-1,y+3),(x-3,y)],'t',True);p.line([(x,y),(x+3,y)],'i');p.line([(x,y+2),(x+3,y+2)],'B')
    if archer:
        x=min(53,front[0]+2);y=31
        p.line([(x-3,y-17),(x+1,y-13),(x+4,y-5),(x+3,y+7),(x,y+14),(x-3,y+17)],'o',4);p.line([(x-3,y-16),(x,y-12),(x+2,y-4),(x+1,y+7),(x-1,y+13),(x-3,y+16)],'B',2);p.line([(x-3,y-16),(x-9 if pose=='windup' else x-3,y),(x-3,y+16)],'y');p.line([(x-7 if pose=='attack' else x-13,y),(min(60 if pose=='attack' else 59,x+7),y)],'t');p.poly([(min(59,x+7),y),(min(57,x+4),y-2),(min(57,x+4),y+2)],'g',True);p.cluster(x-13,y-2,['it','tt','i.'])
    else:
        x,y=front
        if pose=='windup':
            p.poly([(x-1,y+2),(x-9,y-2),(x-15,y-1),(x-18,y-4),(x-16,y-8),(x-11,y-9),(x-8,y-6),(x-7,y-3),(x+1,y)],'t',True);p.line([(x-14,y-7),(x-10,y-6)],'i')
        elif pose=='attack':
            p.poly([(x-2,y+1),(x+10,y-2),(x+13,y-5),(x+18,y-6),(x+20,y-3),(x+20,y+1),(x+15,y+3),(x+11,y+1),(x,y+3)],'t',True);p.poly([(x+13,y-2),(x+17,y-3),(x+18,y),(x+14,y+1)],'i');p.line([(x+1,y+1),(x+10,y-1)],'B')
        else:
            p.poly([(x-2,y+1),(x-1,y-11),(x-3,y-16),(x-2,y-20),(x+3,y-21),(x+6,y-18),(x+5,y-13),(x+2,y-10),(x+1,y+1)],'t',True);p.poly([(x,y-17),(x+3,y-18),(x+4,y-15),(x+1,y-12)],'i');p.line([(x,y-9),(x,y-1)],'B')
    p.part='head';p.pivot=(35,18);skull(p,34,17,1,not archer)
    if archer:p.poly([(26,9),(29,5),(36,4),(43,8),(44,12),(37,10),(31,10),(27,13)],'r',True);p.poly([(29,7),(34,6),(40,8),(38,10),(30,9)],'R');p.line([(30,6),(35,6)],'p');p.poly([(27,9),(21,11),(21,15),(26,13)],'R',True)
    else:p.poly([(27,8),(24,3),(28,4),(31,8)],'t',True);p.line([(27,5),(29,8)],'i');p.poly([(39,7),(43,3),(43,8),(40,11)],'t',True);p.line([(42,5),(41,8)],'i');p.line([(34,6),(33,10),(36,12)],'B')
    return p.im

