    x=end[0]+1;p.line([(x,53),(x,12)],'o',4);p.line([(x,52),(x,12)],'B',2);p.line([(x-1,15),(x-1,46)],'t');p.poly([(x-5,13),(x-6,7),(x-2,3),(x+2,4),(x+6,9),(x+4,14),(x,17)],'s',True);p.poly([(x-2,5),(x+1,6),(x+2,11),(x,14),(x-3,11)],'u');p.line([(x-1,6),(x,11)],'U',2);p.poly([(x-4,11),(x-7,8),(x-7,13),(x-3,15)],'m');p.cluster(x-1,17,['yi']);p.line([(x-3,47),(x+3,47)],'y')
