def bone_spirit(pose,cell):
    p=Pixels(pose,cell);s=SWING[pose]
    if pose=='dead':
        for pts in [[(9,54),(17,53),(24,56)],[(18,48),(25,51),(30,55)],[(24,57),(30,56),(35,59)]]:bone(p,pts,3)
        skull(p,46,48,1);p.poly([(21,59),(25,56),(29,58),(28,60),(23,60)],'t',True);return p.im
    p.part='tail'
    bone(p,[(35,33),(33,36),(30,40)],6)
    for i in range(6):
        x=32-i*3+(s/4 if i%2 else -s/4);y=35+i*4
        p.poly([(x-6,y-2),(x-2,y-4),(x+4,y-3),(x+6,y),(x+3,y+3),(x-3,y+3),(x-6,y+1)],'B',True);p.poly([(x-3,y-2),(x+2,y-2),(x+3,y),(x-2,y+1)],'t');p.line([(x-2,y-2),(x+2,y-2)],'i');p.cluster(x-5,y,['tB','B.'])
        if i<4:
            bone(p,[(x-3,y),(x-8,y-2),(x-11,y+2)],3,True);bone(p,[(x+3,y),(x+8,y+1),(x+10,y+5)],3)
    p.part='head';p.pivot=(40,21);skull(p,39,22,1.45,True);p.poly([(29,10),(25,3),(30,5),(34,10)],'t',True);p.line([(28,5),(32,9)],'i');p.poly([(45,9),(50,3),(51,7),(48,14)],'t',True);p.line([(49,5),(48,10)],'i');p.line([(37,7),(35,13),(38,15)],'B');p.cluster(30,22,['tt','yB','B.'])
    if pose=='attack':p.part='fixed';p.poly([(50,30),(59,28),(56,32),(61,34),(53,37),(49,34)],'V');p.line([(53,31),(57,31)],'L')
    return p.im

def crawler(pose,cell):
    p=Pixels(pose,cell);s=SWING[pose]
    if pose=='dead':
        for pts in [[(9,56),(18,51),(25,57)],[(16,47),(25,48),(31,52)],[(28,57),(34,55),(40,58)]]:bone(p,pts,3)
        skull(p,48,49,.85);skull(p,20,44,.6);p.poly([(25,58),(30,56),(34,58),(33,60),(27,60)],'t',True);return p.im
    p.part='body';p.poly([(11,33),(18,26),(29,24),(41,30),(45,39),(39,44),(28,45),(17,42),(10,38)],'B',True)
    for i in range(6):
        x=16+i*4;y=30+(i-2)**2/2
        p.poly([(x,y-5),(x+3,y-4),(x+4,y),(x+2,y+7),(x+5,y+10),(x+3,y+11),(x-1,y+8),(x-2,y+2),(x-3,y)],'t',True);p.line([(x+1,y-3),(x+2,y+1),(x,y+7)],'i');p.line([(x+3,y+8),(x+4,y+9)],'B')
    for i,(sx,kx,ex) in enumerate([(17,11,9),(24,18,16),(34,43,45),(40,49,53)]):
        p.part='leftleg' if i%2==0 else 'rightleg';bone(p,[(sx,38),(kx,46),(ex,57)],5,i<2);p.poly([(ex-3,57),(ex+2,57),(ex+3,60),(ex-3,60)],'t',True);p.line([(ex-1,58),(ex+1,58)],'i')
    p.part='head';p.pivot=(43,27);skull(p,45,28,1.05,True);p.part='body';skull(p,23,25,.67);p.poly([(11,33),(7,31),(5,27),(7,26),(13,31)],'t',True);p.line([(7,28),(10,31)],'i');p.cluster(25,40,['tBi','BBt']);return p.im

def hand(p,x,y,claw=False,large=False):
    w=5 if large else 4;p.poly([(x-w,y-3),(x+1,y-4),(x+w,y-1),(x+w+1,y+3),(x+2,y+4),(x-w,y+2)],'C',True);p.poly([(x-w+1,y-2),(x,y-2),(x+2,y),(x,y+2),(x-w+2,y+1)],'u');p.cluster(x-2,y-2,['Ug','uC'])
    for i in range(3):
        xx=x+i*2-1;yy=y+2+i%2;p.poly([(xx,yy),(xx+2,yy),(xx+3,yy+4),(xx+1,yy+5),(xx,yy+2)],'t' if claw else 'C',True);p.line([(xx+1,yy+1),(xx+2,yy+3)],'i' if claw else 'u')

