def draw(slug,pose,cell):
    if slug in ('skeleton-archer','skeleton-01'):return skeletal(slug,pose,cell)
    if slug=='lich-frost':return lich(pose,cell)
    if slug=='skeleton-bone':return bone_spirit(pose,cell)
    if slug=='bonepile-crawler':return crawler(pose,cell)
    if slug=='zombie-rot':return rotten(pose,cell)
    if slug=='ghoul-01':return ghoul(pose,cell)
    if slug=='ghoul-grave':return grave(pose,cell)
    if slug=='mummy-bandage':return mummy(pose,cell)
    return armor(slug,pose,cell)
